// Each rule has a test AND a targeted fix. Loop: find the FIRST failing rule,
// apply its fix, re-check — bounded by maxIters so a critique loop cannot run forever.
const RULES = [
  { name: "no-competitor", test: (s) => !/acme/i.test(s), fix: (s) => s.replace(/acme/gi, "our product") },
  { name: "has-cta",       test: (s) => /\b(try|start)\b/i.test(s), fix: (s) => s + " — start today" },
];
function reviseUntilClean(draft, rules, maxIters) {
  let text = draft;
  let iterations = 0;
  while (iterations < maxIters) {
    const failing = rules.find((r) => !r.test(text));
    if (!failing) break;
    text = failing.fix(text);
    iterations++;
  }
  const clean = rules.every((r) => r.test(text));
  return { final: text, iterations, clean };
}
const r = reviseUntilClean("Switch from Acme to save", RULES, 5);
console.log("final:", r.final);
console.log("iterations:", r.iterations);
console.log("clean:", r.clean);

schema-constrained-prompts.code:
// Schema adds an "enum" field type: the value must be one of schema.enums[field].
// Check required, type, enum membership, and unexpected keys — collect every problem.
const schema = {
  fields: { id: "string", qty: "number", size: "enum" },
  enums: { size: ["S", "M", "L"] },
  required: ["id", "qty", "size"],
};
const obj = { id: "A1", qty: 3, size: "XL", note: "hi" };
function checkSchema(obj, schema) {
  const problems = [];
  for (const key of schema.required) if (!(key in obj)) problems.push("missing " + key);
  for (const [key, type] of Object.entries(schema.fields)) {
    if (!(key in obj)) continue;
    if (type === "enum") {
      const allowed = schema.enums[key] || [];
      if (!allowed.includes(obj[key])) problems.push(key + " not in [" + allowed.join(", ") + "]");
    } else if (typeof obj[key] !== type) {
      problems.push(key + " must be " + type);
    }
  }
  for (const key of Object.keys(obj)) if (!(key in schema.fields)) problems.push("unexpected key: " + key);
  return { valid: problems.length === 0, problems };
}
const r = checkSchema(obj, schema);
console.log("valid:", r.valid);
console.log("problems:", r.problems.length);
console.log(r.problems.join(" | "));

