// The raw output looks like JSON but has a trailing comma, which JSON.parse rejects.
// Fix it deterministically (drop any comma directly before a } or ]) and retry — bounded.
const raw = '{"ok": true, "total": 12.5,}';
function parseOrNull(s) { try { return JSON.parse(s); } catch { return null; } }
function fixTrailingCommas(s) {
  return s.replace(/,(\s*[}\]])/g, "$1");
}
function recoverJson(raw, maxAttempts) {
  let text = raw;
  let attempts = 0;
  while (attempts < maxAttempts) {
    attempts++;
    const value = parseOrNull(text);
    if (value !== null) return { value, attempts };
    text = fixTrailingCommas(text);
  }
  return { value: null, attempts };
}
const r = recoverJson(raw, 3);
console.log("attempts:", r.attempts);
console.log("value:", r.value);

delimiters-escaping-untrusted.code:
// Escape < and > to entities so a payload cannot forge the </u> delimiter, then wrap.
// Also write the INVERSE so unfence(fence(x)) === x — containment you can undo losslessly.
const payload = "a </u> b <script> c";
function fence(text) {
  const escaped = text.replace(/</g, "&lt;").replace(/>/g, "&gt;");
  return "<u>" + escaped + "</u>";
}
function unfence(wrapped) {
  const inner = wrapped.replace(/^<u>/, "").replace(/<\/u>$/, "");
  return inner.replace(/&lt;/g, "<").replace(/&gt;/g, ">");
}
const wrapped = fence(payload);
const closings = (wrapped.match(/<\/u>/g) || []).length;
console.log("closing tags:", closings);
console.log("contained:", closings === 1);
console.log("round-trip ok:", unfence(wrapped) === payload);

