// Chunk by WORDS (at most \'per\' words each) so no word is ever split — the boundary
// mistake the worked example warned about. Then MAP each chunk to its count and REDUCE.
const text = "alpha beta gamma delta epsilon zeta eta theta";
const PER = 3;
function chunkWords(t, per) {
  const words = t.split(/\s+/).filter(Boolean);
  const out = [];
  for (let i = 0; i < words.length; i += per) out.push(words.slice(i, i + per));
  return out;
}
function reduceCounts(chunks) {
  return chunks.map((c) => c.length).reduce((a, n) => a + n, 0);
}
const chunks = chunkWords(text, PER);
const total = reduceCounts(chunks);
const boundarySafe = chunks.map((c) => c.join(" ")).join(" ") === text.split(/\s+/).filter(Boolean).join(" ");
