// Scorer is keyword-contains: an output passes a case iff it contains EVERY required
// keyword (case-insensitive, order-free). Report the pass rate AND which inputs failed.
const testSet = [
  { input: "refund status",  must: ["refund", "5-7 days"] },
  { input: "reset password", must: ["reset", "email"] },
  { input: "cancel plan",    must: ["cancel"] },
];
function answer(input) {
  if (input.includes("refund")) return "Your refund posts in 5-7 days.";
  if (input.includes("password")) return "Click reset and check your inbox.";
  return "Your plan is cancelled.";
}
function containsAll(out, keywords) {
  const hay = out.toLowerCase();
  return keywords.every((k) => hay.includes(k.toLowerCase()));
}
function scoreSet(fn, set) {
  const failed = [];
  let pass = 0;
  for (const c of set) {
    if (containsAll(fn(c.input), c.must)) pass++;
    else failed.push(c.input);
  }
  return { pass, total: set.length, rate: pass / set.length, failed };
}
const r = scoreSet(answer, testSet);
console.log("pass:", r.pass, "/", r.total);
console.log("rate:", r.rate.toFixed(2));
console.log("failed:", r.failed.join(", ") || "none");

