// An aggregate pass rate can hide offsetting flips. Compare per case in BOTH directions:
// regressions (pass->fail) and gains (fail->pass), and report the net = gains - regressions.
const before = [ { c: "c1", pass: true }, { c: "c2", pass: true },  { c: "c3", pass: false }, { c: "c4", pass: false } ];
const after  = [ { c: "c1", pass: true }, { c: "c2", pass: false }, { c: "c3", pass: true },  { c: "c4", pass: false } ];
function diffRuns(before, after) {
  const regressed = [], gained = [];
  for (let i = 0; i < before.length; i++) {
    if (before[i].pass && !after[i].pass) regressed.push(before[i].c);
    if (!before[i].pass && after[i].pass) gained.push(before[i].c);
  }
  return { regressed, gained, net: gained.length - regressed.length };
}
const d = diffRuns(before, after);
console.log("regressed:", d.regressed.join(",") || "none");
console.log("gained:", d.gained.join(",") || "none");
console.log("net flips:", d.net);

